def occ(term,row):
 rel,nth,name,kind,label,decision=row; kwic,v=exact_span(rel,term,nth)
 if term=="相瞞" and rel=="M/M59/M59n1540.xml":
  text,_=zc._load(rel); start=text.find(term); kwic=text[start-28:start+len(term)+62].strip(); v=zc.verify(rel,kwic)
  if not v.get('ok'): raise RuntimeError(v)
 contexts=list(EXPLICIT_CONTEXT.get((term,"*"),[]))
 for c in EXPLICIT_CONTEXT.get((term,rel),[]):
  if c not in contexts: contexts.append(c)
 o={"RelPath":rel,"FromLb":v['fromLb'],"ToLb":v['toLb'],"Kwic":kwic,"MasterName":name,"Curated":True,"ContextMasters":contexts,"AttributionNote":f"Source record ({rel}). {SOURCE_LABELS[rel]}: {decision} Headword actor: {label}.","DraftActorProof":{"ExactHeadwordClause":kwic,"GrammaticalSubject":label,"SpeechFrame":decision,"FullCaseDecision":decision}}
 if name:
  o['ContextMasters'].insert(0,{"MasterName":name,"Roles":["utterer"]})
 else:
  unnamed='unnamed' in label
  role="questioner" if "question" in kind else ("verse-author" if "verse" in kind else ("compiler" if "compiler" in kind or "commentator" in kind else "later-quoter"))
  o['ActorAttribution']={"Status":"reviewed-unnamed" if unnamed else "narrated","Kind":kind,"ActorLabel":label,"ActorRole":role,"GrammarEvidence":decision,"ReviewedBy":"Codex Lane C complete-case review","ReviewedUtc":"2026-07-17T12:00:00+00:00","AuthoredVoiceRiskReviewed":True}
  if unnamed: o['ActorAttribution']['RungsChecked']=["line","expanded-context","section-header","book-title","tei-header","parallel-passage"]
 return o

def main():
 for pos in range(7,16):
  id,term,target,alt,aliases,opening,bend,limit=D[pos]; e=E[pos]; os=[occ(term,x) for x in SOURCES[pos]]; works=list(dict.fromkeys(zc.work_id(x['RelPath']) for x in os))
  sense={"SenseKey":None,"MasterName":None,"PreferredTarget":target,"AlternateTargets":[alt],"SearchAliases":aliases,"Status":"preferred","Validation":"multi-source","ExplanationParts":{"CorpusEarnedOpening":opening,"EvidenceBody":e['body']},"Note":e['note'],"Occurrences":os,"ClaimAnchors":[],"SourceTexts":[x['RelPath'] for x in os],"RelatedMasters":list(dict.fromkeys(x['MasterName'] for x in os if x.get('MasterName'))),"RelatedTerms":[x['Term'] for x in e['fam']],"DraftEvidence":{"OpeningClaimEvidenceKeys":[f"o{i}" for i in range(1,len(os)+1)],"ZenBend":bend,"CounterexampleOrLimit":limit,"DifferentThingTest":{"Decision":"one-thing","ComparedThings":e['diff']['ComparedThings'],"Reason":e['diff']['Reason']},"AliasRationale":e['alias'],"ModifierControls":e['mod'],"FamilyControls":e['fam'],"IndependentWorkIds":works}}
  w={"SchemaVersion":1,"Entry":{"Id":id,"SourceTerm":term,"CorpusBaselineSha256":BASELINE,"CreatedBy":"Codex construction Lane C evidence-first","WrittenUtc":datetime.now(timezone.utc).isoformat(),"Senses":[sense]}}
  out=DB/'fresh-build'/'entries'/id; out.mkdir(parents=True,exist_ok=True); (out/'evidence.draft.json').write_text(json.dumps(w,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
  (out/'WORK.md').write_text(f"# {term} — construction Lane C position {pos}\n\n- corpus baseline: `{BASELINE}`\n- depth: {len(os)} exact witnesses across {len(works)} independent works\n- actor review: every occurrence was decided from its complete turn; null MasterName is used for monk, compiler, or unresolved non-roster utterers rather than misattributing the headword.\n\nfeedback-observations: {opening}\nfeedback-inference-verdict: {bend}\nfeedback-falsification-searches: {limit}\nfeedback-counterexamples: {e['note']}\nfeedback-scope: {e['diff']['Reason']}\nlookup-probes: {'; '.join(aliases)}. {e['alias']}\nopening-interpretation-verdict: {e['body'][0]}\n\nsense-target-distinguishability: {e['diff']['Reason']}\nfamily-control: {'; '.join(x['Term']+': '+x['Finding'] for x in e['fam'])}\n",encoding='utf-8')
  print(pos,id,term)
if __name__=='__main__': main()
